class Session {
    mutable std::atomic<unsigned> refs_{0};          // count lives in the body
    friend void intrusive_ptr_add_ref(const Session* s) {
        s->refs_.fetch_add(1, std::memory_order_relaxed);
    }
    friend void intrusive_ptr_release(const Session* s) {
        if (s->refs_.fetch_sub(1, std::memory_order_acq_rel) == 1) delete s;
    }
public:
    static boost::intrusive_ptr<Session> create() { return {new Session}; }
};
boost::intrusive_ptr<Session> a = Session::create(), b = a;   // one increment, no allocation

