class Buffer : public boost::intrusive_ref_counter<Buffer, boost::thread_safe_counter> {
    std::vector<std::byte> data_;
public:
    explicit Buffer(std::size_t n) : data_(n) {}
};

boost::intrusive_ptr<Buffer> make() { return new Buffer(4096); }  // no control block

void intrusive_ptr_add_ref(IUnknown* p) { p->AddRef(); }
void intrusive_ptr_release(IUnknown* p) { p->Release(); }

boost::intrusive_ptr<IUnknown> adopt(IUnknown* owned) {
    return boost::intrusive_ptr<IUnknown>(owned, false);  // caller's ref moves in
}
